import { readFile, writeFile } from "node:fs/promises";
import { resolve } from "node:path";
import process from "node:process";

const root = resolve(import.meta.dirname, "..");
const sourcePath = resolve(root, "examples/bathroom-pay.miniapp.js");
const outputPath = resolve(
  root,
  "apps/mobile/src/generated/bathroom-pay-source.ts",
);

const source = await readFile(sourcePath, "utf8");
const output = [
  "// Generated by scripts/sync-example-source.mjs. Do not edit directly.",
  "export const BATHROOM_PAY_SOURCE =",
  `  ${JSON.stringify(source)};`,
  "",
].join("\n");

if (process.argv.includes("--check")) {
  const current = await readFile(outputPath, "utf8").catch(() => "");
  if (current !== output) {
    console.error("Bundled Bathroom Pay source is stale. Run pnpm sync:examples.");
    process.exitCode = 1;
  }
} else {
  await writeFile(outputPath, output);
}
